// CSRF для cookie-сессии: double-submit токен (пакет csurf больше не поддерживается)
import { randomBytes, timingSafeEqual } from "node:crypto";

app.get("/csrf-token", (req, res) => {
  const token = randomBytes(32).toString("hex");
  res.cookie("csrf", token, { sameSite: "strict", secure: true });
  res.json({ csrfToken: token });
});

// требует cookie-parser; клиент присылает токен в заголовке X-CSRF-Token
function csrfProtect(req, res, next) {
  if (["GET", "HEAD", "OPTIONS"].includes(req.method)) return next();
  const cookie = Buffer.from(req.cookies.csrf ?? "");
  const header = Buffer.from(req.get("x-csrf-token") ?? "");
  if (!cookie.length || cookie.length !== header.length || !timingSafeEqual(cookie, header)) {
    return res.status(403).json({ error: "CSRF token mismatch" });
  }
  next();
}
